#!/bin/sh
# QuecTool on-modem installer. Run from the unpacked tarball directory:
#   sh install.sh
#
# Layout produced:
#   /usrdata/quectool/quectool         binary
#   /usrdata/quectool/quectool.yaml    config (preserved across upgrades)
#   /usrdata/quectool/server.{crt,key} TLS cert (auto-generated by the
#                                      binary on first boot)
#   /lib/systemd/system/quectool.service
#   /lib/systemd/system/multi-user.target.wants/quectool.service  (symlink)
#
# Idempotent. Safe to re-run for upgrades.

set -e

if [ "$(id -u)" != "0" ]; then
    echo "install.sh: must run as root" >&2
    exit 1
fi

HERE=$(cd "$(dirname "$0")" && pwd)
INSTALL_DIR=/usrdata/quectool
UNIT_SRC="$HERE/quectool.service"
UNIT_DST=/lib/systemd/system/quectool.service
WANTS_DIR=/lib/systemd/system/multi-user.target.wants

for f in quectool quectool.yaml quectool.service uninstall.sh; do
    if [ ! -f "$HERE/$f" ]; then
        echo "install.sh: missing $f next to installer" >&2
        exit 1
    fi
done

remount() {
    mount -o "remount,$1" / 2>/dev/null || true
}

echo "==> remounting / read-write"
remount rw

echo "==> installing binary to $INSTALL_DIR"
mkdir -p "$INSTALL_DIR"
# Atomic replace: cp into a sibling, chmod, then rename(2) over the
# target. Plain `cp` over a running ELF fails with ETXTBSY because it
# truncates the existing inode (which is mmap'd by the running process).
# rename atomically swaps the inode — the running process keeps its old
# one; the path is updated to point at the new file. Restart picks up
# the new binary.
cp "$HERE/quectool" "$INSTALL_DIR/quectool.new"
chmod 0755 "$INSTALL_DIR/quectool.new"
mv -f "$INSTALL_DIR/quectool.new" "$INSTALL_DIR/quectool"

# First-install only: drop the default config. On upgrades, leave the
# operator's edits alone — write the new defaults next to it for diffing.
if [ -f "$INSTALL_DIR/quectool.yaml" ]; then
    echo "==> preserving existing $INSTALL_DIR/quectool.yaml"
    cp "$HERE/quectool.yaml" "$INSTALL_DIR/quectool.yaml.new"
    echo "    (new defaults written to quectool.yaml.new for review)"
else
    echo "==> writing default $INSTALL_DIR/quectool.yaml"
    cp "$HERE/quectool.yaml" "$INSTALL_DIR/quectool.yaml"
fi

echo "==> installing uninstaller for later"
cp "$HERE/uninstall.sh" "$INSTALL_DIR/uninstall.sh"
chmod 0755 "$INSTALL_DIR/uninstall.sh"

echo "==> installing systemd unit"
cp "$UNIT_SRC" "$UNIT_DST"
mkdir -p "$WANTS_DIR"
ln -sf "$UNIT_DST" "$WANTS_DIR/quectool.service"

echo "==> reloading systemd & restarting service"
systemctl daemon-reload
# restart = stop-if-running + start. Handles first install (just starts)
# and upgrade (replaces the running process with one that execs the new
# binary at the same path).
systemctl restart quectool

echo "==> remounting / read-only"
remount ro

VERSION=$("$INSTALL_DIR/quectool" --version 2>/dev/null || echo unknown)
PORT=$(awk '/^[[:space:]]*port:/ { gsub(/"/, "", $2); print $2; exit }' "$INSTALL_DIR/quectool.yaml" 2>/dev/null || echo 443)
TLS=$(awk '/^[[:space:]]*tls:/ { print $2; exit }' "$INSTALL_DIR/quectool.yaml" 2>/dev/null || echo true)
SCHEME=https
if [ "$TLS" = "false" ]; then SCHEME=http; fi

cat <<EOF

QuecTool $VERSION installed.
  config: $INSTALL_DIR/quectool.yaml
  unit:   $UNIT_DST
  url:    $SCHEME://<modem-ip>:$PORT

Tail logs:    journalctl -u quectool -f
Edit config:  vi $INSTALL_DIR/quectool.yaml && systemctl restart quectool
EOF
